import React from 'react';
import { View, TouchableOpacity, Text, StyleSheet, Platform } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';

export default function BottomActionBar({
  onNovoEnsaio,
  onNovoDevocional,
  onEditarDevocional,
}) {
  return (
    <View style={styles.wrapper}>
      <LinearGradient
        colors={['#3a256b', '#4b1e6d', '#2d145e']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.container}
      >
        <View style={[styles.sideBtn, { marginRight: 24 }]}>
          <TouchableOpacity style={[styles.actionBtn, styles.skeuoBtn]} onPress={onNovoEnsaio}>
            <Text style={styles.icon}>📒</Text>
            <Text style={styles.label}>+Ensaio</Text>
          </TouchableOpacity>
        </View>

        <View style={styles.centerBtnWrapper}>
          <TouchableOpacity style={[styles.centerBtn, styles.skeuoCenterBtn]} onPress={onNovoDevocional}>
            <Text style={styles.centerIcon}>🧎‍♂️</Text>
          </TouchableOpacity>
          <Text style={styles.centerLabel}>+Devocional</Text>
        </View>

        <View style={[styles.sideBtn, { marginLeft: 24 }]}>
          <TouchableOpacity style={[styles.actionBtn, styles.skeuoBtn]} onPress={onEditarDevocional}>
            <Text style={styles.icon}>🙏</Text>
            <Text style={styles.label}>Editar</Text>
          </TouchableOpacity>
        </View>
      </LinearGradient>
    </View>
  );
}

const skeuoShadow = {
  shadowColor: '#1a093e',
  shadowOffset: { width: 0, height: 8 },
  shadowOpacity: 0.35,
  shadowRadius: 18,
  elevation: 18,
};

const innerShadow = {
  shadowColor: '#a084e8',
  shadowOffset: { width: -4, height: -4 },
  shadowOpacity: 0.18,
  shadowRadius: 8,
  elevation: 8,
};

const styles = StyleSheet.create({
  wrapper: {
    position: 'absolute',
    left: 0,
    right: 0,
    bottom: 0,
    alignItems: 'center',
    zIndex: 99,
  },
  container: {
    flexDirection: 'row',
    borderTopLeftRadius: 32,
    borderTopRightRadius: 32,
    height: 90,
    alignItems: 'flex-end',
    justifyContent: 'space-between',
    width: '96%',
    marginHorizontal: '2%',
    backgroundColor: '#2d145e',
    ...skeuoShadow,
    paddingHorizontal: 18,
    paddingBottom: Platform.OS === 'ios' ? 18 : 8,
    borderWidth: 2,
    borderColor: '#3a256b',
  },
  sideBtn: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'flex-end',
    height: 90,
  },
  actionBtn: {
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 18,
    paddingVertical: 8,
    paddingHorizontal: 12,
    marginBottom: 8,
  },
  skeuoBtn: {
    backgroundColor: '#3a256b',
    ...skeuoShadow,
    ...innerShadow,
    borderWidth: 1,
    borderColor: '#4b1e6d',
  },
  icon: {
    fontSize: 28,
    color: '#fff',
    textShadowColor: '#1a093e',
    textShadowOffset: { width: 1, height: 2 },
    textShadowRadius: 4,
  },
  label: {
    fontSize: 13,
    color: '#fff',
    marginTop: 2,
    fontWeight: 'bold',
    textShadowColor: '#1a093e',
    textShadowOffset: { width: 1, height: 1 },
    textShadowRadius: 2,
  },
  centerBtnWrapper: {
    position: 'absolute',
    left: '50%',
    top: -36,
    transform: [{ translateX: -40 }],
    alignItems: 'center',
    zIndex: 10,
  },
  centerBtn: {
    width: 72,
    height: 72,
    borderRadius: 36,
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 4,
    borderColor: '#fff',
    marginBottom: 2,
  },
  skeuoCenterBtn: {
    backgroundColor: '#4b1e6d',
    ...skeuoShadow,
    ...innerShadow,
    borderWidth: 2,
    borderColor: '#a084e8',
  },
  centerIcon: {
    fontSize: 38,
    color: '#fff',
    textShadowColor: '#1a093e',
    textShadowOffset: { width: 1, height: 2 },
    textShadowRadius: 4,
  },
  centerLabel: {
    color: '#fff',
    fontSize: 13,
    fontWeight: 'bold',
    marginTop: 2,
    textAlign: 'center',
    textShadowColor: '#1a093e',
    textShadowOffset: { width: 1, height: 1 },
    textShadowRadius: 2,
  },
});